#define PI 3.14159
#define OBJ_GROUP_0 0
#define OBJ_GROUP_1 1
#define OBJ_GROUP_2 2
#define OBJ_GROUP_3 3
float rand(float seed) {
    return fract(sin(seed)*100000.0);
}
mat2 rot2D(float angle) {
    float c = cos(angle);
    float s = sin(angle);

    return mat2(c, -s, s, c);
}

vec3 proj(vec3 u, vec3 v) {
    return v*(dot(u, v)/ dot(v, v));
}

//Signed distance & smooth union from Inigo Quilez
float sdSphere( vec3 ray, float size ) {
  return length(ray)-size;
}

float sdBox( vec3 ray, vec3 dimensions ) {
  vec3 q = abs(ray) - dimensions;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float sdPlane( vec3 ray, vec3 normal, float height ) {
  normal = normalize(normal);
  return dot(ray,normal) + height;
}


float opSmoothUnion( float d1, float d2, float k ) {
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

//Object definition
float getDist(vec3 ray, float t) {
    vec3 r1 = ray;
    vec3 r2 = ray;

    ray.z -= .5 +sin(ray.x + t);
    ray = fract(ray) -.5;

    r1.x -= t + cos(r1.z+t*0.1);
    r1 = fract(r1) - .5;

    r2.y -= 0.5*t+sin(r2.x + t*0.2);
    r2.x -= 2.*t;
    r2 = fract(r2) - .5;


    float d1 = sdSphere(ray, 0.3);
    float d2 = sdSphere(r1, 0.2);
    float d3 = sdSphere(r2, 0.1);

    float d = opSmoothUnion( d1, d2, .5);
    d = opSmoothUnion( d, d3, .4);
    return d;

}

//From Art of Code
vec3 getNormal(vec3 p, float t) {
    vec2 e = vec2(.001, 0);
    vec3 n = getDist(p, t) - 
        vec3(getDist(p-e.xyy, t), getDist(p-e.yxy, t),getDist(p-e.yyx, t));

    return normalize(n);
}

// textures objeccts based on ray
vec3 textureObj(vec3 ray, float t) {
    vec3 colXZ;
    vec3 colXY;
    vec3 colYZ;

    ray = fract(ray);
    colXZ = texture(iChannel0, ray.xz * 0.25 + 0.5).rgb;
    colXY = texture(iChannel0, ray.xy * 0.5 + 0.5).rgb;
    colYZ = texture(iChannel0, ray.yz * 0.5 + 0.5).rgb;


    vec3 normal = getNormal(ray, t);

    return colXZ * abs(normal.y) + colXY * abs(normal.z) + colYZ * abs(normal.x);
}
//Returns colour of object
vec3 raymarch(vec3 origin, vec3 ray, float t) {
    float totDist = 0.0;
    int iterations = 80;
    vec3 colour = vec3(1.0);

    for (int i = 0; i < 256; i++) {
        vec3 pos = origin + ray * totDist;
        float dist = getDist(pos, t);

        totDist += dist;

        if (dist <= 0.0001) {
            iterations = i;
            colour = textureObj(pos, t);
            break;
        } else if (dist >= 100.0 || i == 79) {
            iterations = i;
            colour = vec3(0.0);
            break;
        }
    }

    vec3 finalRay = origin + ray * totDist;
    vec3 outlineCol = (0.5 + 0.5*cos(totDist - t*15. + vec3(1,2,5)))*float(iterations)/80.;
    return clamp(outlineCol*.7 + totDist*0.01, 0.0, 1.0);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // uv made for raymarching
    vec2 uv = (fragCoord *2. - iResolution.xy) / iResolution.y;

    // Camera Definition
    float t = iTime*.4;
    vec3 origin = vec3(t*5., 0.0, 0.0);
    vec3 ray = normalize(vec3(uv, 10.0));

    // Camera Rotation
    ray.xz *= rot2D(sin(t)*0.1-PI/2.);
    ray.xy *= rot2D(sin(t*.5)*0.015);
    ray.zy *= rot2D(sin(t)*0.2 + t*0.15);
    // Time varying pixel color
    vec3 col = raymarch(origin, ray, t);

    // Output to screen
    fragColor = vec4(col,1.0);
}
